using System;using System.Linq;using AntColony.Core;using AntColony.Units;using AntColony.Data;using AntColony.Save;using UnityEngine;
public static class Dining1114Fourth {public static string Run(){if(string.IsNullOrEmpty(SaveStorage.RootOverride))throw new Exception("Isolated save required");var roster=CommanderRoster.Instance;var first=roster.Commanders.First(c=>c&&c.IsColonyMember);var c=roster.Commanders.Count>=4 ? first : roster.Create("Dining fourth",CommanderRank.Sergeant,new[]{UnitRole.Worker,UnitRole.Melee},UnitRole.Worker,CommanderTraits.Random(),first.Agent.nextPosition+Vector3.right*3);if(!c)throw new Exception("Create failed");foreach(var actor in roster.Commanders){actor.PersonalState.meal.eatSeconds=0;actor.CommandMove(actor.Agent.nextPosition);actor.CommandStop();}return "Created fourth through normal roster factory; eating reset for test";}}
